    private func _parseChord(_ beat: Beat, _ element: XmlNode) {
        let articulation: Note = Note()
        for c in element.childElements() {
            switch c.localName! {
            case "stem":
                switch c.getAttribute("dir") {
                case "up":
                    beat.preferredBeamDirection = BeamDirection.Up
                case "down":
                    beat.preferredBeamDirection = BeamDirection.Down
                default:
                    break
                }
            case "articulation":
                switch c.getAttribute("type") {
                case "staccato":
                    articulation.isStaccato = true
                case "normalAccent":
                    articulation.accentuated = AccentuationType.Normal
                case "strongAccent":
                    articulation.accentuated = AccentuationType.Heavy
                default:
                    break
                }
            case "lyric":
                self._parseLyric(beat, c)
            case "drawObjects":
                self._parseBeatDrawObject(beat, c)
            case "heads":
                self._parseHeads(beat, articulation, c)
            case "beam":
                switch c.getAttribute("group") {
                case "force":
                    beat.beamingMode = BeatBeamingMode.ForceMergeWithNext
                case "divide":
                    beat.beamingMode = BeatBeamingMode.ForceSplitToNext
                default:
                    break
                }
            default:
                break
            }
        }
    }

