                            self.score.artist = (obj as! TextDrawObject).text
                        } else if self._isFirstSystem && self.score.music == "" && (obj as! TextDrawObject).align == TextAlign.Right && (obj as! TextDrawObject).y < 0 {
                            self.score.music = (obj as! TextDrawObject).text
                        } else if !(obj as! TextDrawObject).text.startsWith("by capella") {
                            beat.text = (obj as! TextDrawObject).text
                        }
                    } else if obj! is GuitarDrawObject {
                    } else if obj! is WavyLineDrawObject {
                        beat.vibrato = VibratoType.Slight
                    } else if obj! is WedgeDrawObject {
                        beat.crescendo = (obj as! WedgeDrawObject).decrescendo ? CrescendoType.Decrescendo : CrescendoType.Crescendo
                        (obj as! WedgeDrawObject).noteRange += 1
                        self._crescendo.set(beat, (obj as! WedgeDrawObject))
                    } else if obj! is SlurDrawObject {
                        let slur: SlurDrawObject = ((obj as Any) as! SlurDrawObject)
                        self._slurs.set(beat, slur)
                    } else if obj! is VoltaDrawObject {
                        self._applyVolta((obj as! VoltaDrawObject))
                    }
                }
            default:
                break
            }
        }
    }

    private func _parseBarDrawObject(_ element: XmlNode) {
        for c in element.childElements() {
            switch c.localName! {
            case "drawObj":
                let obj: DrawObject? = self._parseDrawObj(c)
                if TypeHelper.isTruthy(obj) {
                    if obj! is VoltaDrawObject {
                        self._applyVolta((obj as! VoltaDrawObject))
                    }
                }
            default:
                break
            }
        }
    }

    private func _applyVolta(_ obj: VoltaDrawObject) {
        if obj.lastNumber > 0 {
            self._currentVoiceState.repeatCount = obj.lastNumber
            if TypeHelper.isTruthy(TypeHelper.isTruthy(self._currentVoiceState.repeatEnd) && self._currentVoiceState.repeatEnd!.repeatCount < self._currentVoiceState.repeatCount) {
                self._currentVoiceState.repeatEnd!.repeatCount = self._currentVoiceState.repeatCount
            }
        } else if obj.firstNumber > 0 {
            self._currentVoiceState.repeatCount = obj.firstNumber
            if TypeHelper.isTruthy(TypeHelper.isTruthy(self._currentVoiceState.repeatEnd) && self._currentVoiceState.repeatEnd!.repeatCount < self._currentVoiceState.repeatCount) {
                self._currentVoiceState.repeatEnd!.repeatCount = self._currentVoiceState.repeatCount
            }
        }
        if obj.lastNumber > 0 && obj.firstNumber > 0 {
            var alternateEndings: Double = 0.0
            do {
                var i: Double = obj.firstNumber
                while i <= obj.lastNumber {
                    alternateEndings = jsOr(alternateEndings, jsShl(1, i - 1.0))
                    i += 1
                }
            }
            self._currentBar.masterBar.alternateEndings = alternateEndings
        } else if obj.lastNumber > 0 {
            self._currentBar.masterBar.alternateEndings = jsShl(1, obj.lastNumber - 1.0)
        } else if obj.firstNumber > 0 {
            self._currentBar.masterBar.alternateEndings = jsShl(1, obj.firstNumber - 1.0)
        }
    }

    private func _parseLyric(_ beat: Beat, _ element: XmlNode) {
        for c in element.childElements() {
            switch c.localName! {
            case "verse":
                if !TypeHelper.isTruthy(beat.lyrics) {
                    beat.lyrics = List<String>()
                }
                var text: String = c.innerText
                if c.getAttribute("hyphen") == "true" {
                    text += "-"
                }
                beat.lyrics!.push(text)
            default:
                break
            }
        }
    }

    private func _parseRestDurations(_ element: XmlNode) -> Beat? {
        let durationBase: String = element.getAttribute("base")
        if durationBase.indexOfInDouble("/") != -1.0 {
            let restBeat: Beat = Beat()
            restBeat.beamingMode = self._beamingMode
            self._parseDuration(restBeat, element)
            return restBeat
        }
        let fullBars: Double = Number.parseInt(durationBase, 10.0)
        if fullBars == 1.0 {
            let restBeat: Beat = Beat()
            restBeat.beamingMode = self._beamingMode
            restBeat.duration = Duration.Whole
            return restBeat
        }
        Logger.warning("Importer", "Multi-Bar rests are not supported")
        return nil
    }

    private func _parseDurationValue(_ s: String) -> Duration {
        switch s {
        case "2/1":
            return Duration.DoubleWhole
        case "1/1":
            return Duration.Whole
        case "1/2":
            return Duration.Half
        case "1/4":
            return Duration.Quarter
        case "1/8":
            return Duration.Eighth
        case "1/16":
            return Duration.Sixteenth
        case "1/32":
            return Duration.ThirtySecond
        case "1/64":
            return Duration.SixtyFourth
        case "1/128":
            return Duration.OneHundredTwentyEighth
        default:
            Logger.warning("Importer", "Unsupported duration")
            return Duration.Quarter
        }
    }

    private func _parseDuration(_ beat: Beat, _ element: XmlNode) {
        let durationBase: String = element.getAttribute("base")
        beat.duration = self._parseDurationValue(durationBase)
        if element.attributes.has("dots") {
            beat.dots = Number.parseInt(element.attributes.get("dots")!, 10.0)
        }
        let tuplet: XmlNode? = element.findChildElement("tuplet")
        if TypeHelper.isTruthy(tuplet) {
            beat.tupletNumerator = Number.parseInt(tuplet!.getAttribute("count"), 10.0)
            let tripartiteMultiplicator: Double = tuplet!.getAttribute("tripartite") == "true" ? 3.0 : 1.0
            let prolongDiff: Double = tuplet!.getAttribute("prolong") == "true" ? 0.0 : 1.0
            var power: Double = 0.0
            while tripartiteMultiplicator * Math.pow(2.0, power + prolongDiff) < beat.tupletNumerator {
                power += 1
            }
            beat.tupletDenominator = tripartiteMultiplicator * Math.pow(2.0, power)
        }
    }

    private func _parsePageObjects(_ element: XmlNode) {
        for c in element.childElements() {
            switch c.localName! {
            case "drawObj":
                let obj: DrawObject? = self._parseDrawObj(c)
                if TypeHelper.isTruthy(obj) {
                    if obj! is TextDrawObject {
                        switch (obj as! TextDrawObject).align {
                        case TextAlign.Center:
                            if !TypeHelper.isTruthy(self.score.title) {
                                self.score.title = c.innerText
                            } else if !TypeHelper.isTruthy(self.score.subTitle) {
                                self.score.subTitle = c.innerText
                            }
                        case TextAlign.Right:
                            if !TypeHelper.isTruthy(self.score.artist) {
                                self.score.artist = c.innerText
                            }
                        default:
                            break
                        }
                    }
                }
            default:
                break
            }
        }
    }

    private func _parseGallery(_ element: XmlNode) {
        for c in element.childElements() {
            switch c.localName! {
            case "drawObj":
                let obj: DrawObject? = self._parseDrawObj(c)
                if TypeHelper.isTruthy(obj) {
                    self._galleryObjects.set(c.getAttribute("name"), obj!)
                }
            default:
                break
            }
        }
    }

    private func _parseDrawObj(_ element: XmlNode) -> DrawObject? {
        var obj: DrawObject? = nil
        var noteRange: Double = 1.0
        for c in element.childElements() {
            switch c.localName! {
            case "text":
                obj = self._parseText(c)
            case "guitar":
                obj = self._parseGuitar(c)
            case "slur":
                obj = self._parseSlur(c)
            case "wavyLine":
                obj = self._parseWavyLine(c)
            case "bracket":
                obj = self._parseTupletBracket(c)
            case "wedge":
                obj = self._parseWedge(c)
            case "volta":
                obj = self._parseVolta(c)
            case "octaveClef":
                obj = self._parseOctaveClef(c)
            case "trill":
                obj = self._parseTrill(c)
            case "basic":
                if c.attributes.has("noteRange") {
                    noteRange = Number.parseInt(c.attributes.get("noteRange")!, 10.0)
                }
            default:
                break
            }
        }
        if TypeHelper.isTruthy(obj) {
            obj!.noteRange = noteRange
        }
        return obj
    }

    private func _parseTrill(_ _unused: XmlNode) -> DrawObject? {
        let obj: TrillDrawObject = TrillDrawObject()
        return obj
    }

    private func _parseOctaveClef(_ element: XmlNode) -> OctaveClefDrawObject {
        let obj: OctaveClefDrawObject = OctaveClefDrawObject()
        if element.attributes.has("octave") {
            obj.octave = Number.parseInt(element.attributes.get("octave")!, 10.0)
        }
        return obj
    }

    private func _parseVolta(_ element: XmlNode) -> VoltaDrawObject {
        let obj: VoltaDrawObject = VoltaDrawObject()
        obj.allNumbers = element.attributes.get("allNumbers") == "true"
        if element.attributes.has("firstNumber") {
            obj.firstNumber = Number.parseInt(element.attributes.get("firstNumber")!, 10.0)
        }
        if element.attributes.has("lastNumber") {
            obj.lastNumber = Number.parseInt(element.attributes.get("lastNumber")!, 10.0)
        }
        return obj
    }

    private func _parseWedge(_ element: XmlNode) -> WedgeDrawObject {
        let obj: WedgeDrawObject = WedgeDrawObject()
        obj.decrescendo = element.attributes.get("decrescendo") == "true"
        return obj
    }

    private func _parseTupletBracket(_ element: XmlNode) -> TupletBracketDrawObject {
        let obj: TupletBracketDrawObject = TupletBracketDrawObject()
        if element.attributes.has("number") {
            obj.number = Number.parseInt(element.attributes.get("number")!, 10.0)
        }
        return obj
    }

    private func _parseWavyLine(_ _unused: XmlNode) -> WavyLineDrawObject {
        let obj: WavyLineDrawObject = WavyLineDrawObject()
        return obj
    }

    private func _parseSlur(_ _unused: XmlNode) -> SlurDrawObject {
        let obj: SlurDrawObject = SlurDrawObject()
        return obj
    }

    private func _parseGuitar(_ element: XmlNode) -> GuitarDrawObject {
        let obj: GuitarDrawObject = GuitarDrawObject()
        let strings: String = element.innerText.trim()
        do {
            var i: Double = 0.0
            while i < strings.length {
                if strings.charAt(i) == "/" {
                    obj.chord.strings.push(0.0)
                } else {
                    obj.chord.strings.push(Number.parseInt(strings.charAt(i), 10.0))
                }
                i += 1
            }
        }
        return obj
    }

    private func _parseText(_ element: XmlNode) -> TextDrawObject {
        let obj: TextDrawObject = TextDrawObject()
        if element.attributes.has("x") {
            obj.x = Number.parseFloat(element.attributes.get("x")!)
        }
        if element.attributes.has("x") {
            obj.y = Number.parseFloat(element.attributes.get("y")!)
        }
        switch element.getAttribute("align") {
        case "left":
            obj.align = TextAlign.Left
        case "center":
            obj.align = TextAlign.Center
        case "right":
            obj.align = TextAlign.Right
        default:
            break
        }
        switch element.getAttribute("frame") {
        case "rectangle":
            obj.frame = FrameType.Rectangle
        case "ellipse":
            obj.frame = FrameType.Ellipse
        case "circle":
            obj.frame = FrameType.Circle
        case "none":
            obj.frame = FrameType.None
        default:
            break
        }
        if TypeHelper.isTruthy(element.firstElement) {
            for c in element.childElements() {
                switch c.localName! {
                case "font":
                    obj.fontFace = c.getAttribute("face")
                    if c.attributes.has("weight") {
                        obj.weight = Number.parseInt(c.attributes.get("weight")!, 10.0)
                    }
                    if c.attributes.has("height") {
                        obj.height = Number.parseInt(c.attributes.get("height")!, 10.0)
                    }
                case "content":
                    obj.text = c.innerText
                default:
                    break
                }
            }
        } else {
            obj.text = element.innerText
        }
        return obj
    }

    private func _parseInfo(_ element: XmlNode) {
        for c in element.childElements() {
            switch c.localName! {
            case "author":
                self.score.tab = c.innerText
            case "comment":
                self.score.notices = c.innerText
            default:
                break
            }
        }
    }

    public init() {}
}

internal class DrawObject {
    public var noteRange: Double = 1.0

    public var x: Double = 0.0

    public var y: Double = 0.0

    public init() {}
}

internal enum FrameType: Int, IAlphaTabEnum, CaseIterable {
    case None = 0
    case Rectangle = 1
    case Ellipse = 2
    case Circle = 3
}

internal final class TextDrawObject: DrawObject {
    public var align: TextAlign = TextAlign.Left

    public var frame: FrameType = FrameType.None

    public var text: String = ""

    public var fontFace: String = ""

    public var weight: Double = 0.0

    public var height: Double = 0.0

    public override init() {
        super.init()
    }
}

internal final class GuitarDrawObject: DrawObject {
    public var chord: Chord = Chord()

    public override init() {
        super.init()
    }
}

internal final class SlurDrawObject: DrawObject {
    public override init() {
        super.init()
    }
}

internal final class WavyLineDrawObject: DrawObject {
    public override init() {
        super.init()
    }
}

internal final class TupletBracketDrawObject: DrawObject {
    public var number: Double = 0.0

    public override init() {
        super.init()
    }
}

internal final class WedgeDrawObject: DrawObject {
    public var decrescendo: Bool = false

    public override init() {
        super.init()
    }
}

internal final class VoltaDrawObject: DrawObject {
    public var allNumbers: Bool = false

    public var firstNumber: Double = 0.0

    public var lastNumber: Double = 0.0

    public override init() {
        super.init()
    }
}

internal final class OctaveClefDrawObject: DrawObject {
    public var octave: Double = 1.0

    public override init() {
        super.init()
    }
}

internal final class TrillDrawObject: DrawObject {
    public override init() {
        super.init()
    }
}

internal final class StaffLayout {
    public var defaultClef: Clef = Clef.G2

    public var description: String = ""

    public var percussion: Bool = false

    public var instrument: Double = 0.0

    public var volume: Double = 0.0

    public var transpose: Double = 0.0

    public var index: Double = 0.0

    public init() {}
}

internal final class Bracket {
    public var from: Double = 0.0

    public var to: Double = 0.0

    public var curly: Bool = false

    public init() {}
}

internal final class CapellaVoiceState {
    public var currentBarIndex: Double = -1.0

    public var currentBarComplete: Bool = true

    public var currentBarDuration: Double = 0.0

    public var currentPosition: Double = 0.0

    public var voiceStemDir: BeamDirection? = nil

    public var repeatCount: Double = 0.0

    public var repeatEnd: MasterBar? = nil

    public init() {}
}
